rows=[json.loads(l) for l in open('/tmp/taxjudge-bundles/E31/trajectory.jsonl')]
out=pathlib.Path('/tmp/e31-readable');out.mkdir(exist_ok=True)
for name,start,end in [('01-opening',1,25),('02a-ontology',26,30),('02b-safety',31,35),('02c-reporting',36,40),('02d-harness',41,45),('03-synthesis',46,82),('04-injection',83,146),('05-citation',147,193),('06-ending',194,233)]:
 chunks=[]
 for i in range(start,end+1):
  x=rows[i-1];typ=x.get('type')
  if typ not in ('user','assistant','system','queue-operation'): continue
  chunks.append(f'\n===== SOURCE LINE {i} | {x.get("timestamp", "")} | {typ} =====\n')
  if typ in ('system','queue-operation'):
   chunks.append(json.dumps(x,ensure_ascii=False)); continue
  c=x.get('message',{}).get('content',[])
  if isinstance(c,str):chunks.append(c);continue
  for b in c:
   bt=b.get('type')
